function gedV5Extras(i){return i<30?GED_COUNT_EXTRA_1_30[i]:GED_COUNT_EXTRA_31_60[i+1];}
function gedV5IconMap(i,extras){
 const out={}; for(const [label,key] of extras){
  if(['@책','@인물','@깃발','@색종이','card'].includes(key))continue;
  if(key==='@SVG')out[label]={svg:GED_COUNT_EXTRA_SVG_1_30[label]};
  else if(key.startsWith('@'))out[label]={file:key.slice(1).replace(/\.jpg$/,'')};
  else if(i>=30&&GED_COUNT_EXTRA_PATHS_31_60[key])out[label]={svg:GED_COUNT_EXTRA_PATHS_31_60[key]};
  else out[label]={file:key};
 }return out;
}
function gedV5Scene(scene,i,choice){
 if(i===34)return {...scene,v5:true,name:choice?'월 선택 카드':'월 카드',iconName:'월 카드',items:Array.from({length:10},(_,k)=>`${k+1}월`)};
 const extra=gedV5Extras(i);return {...scene,v5:true,items:[...scene.items,...extra.map(x=>x[0])],v5Icons:gedV5IconMap(i,extra)};
}
