 const isBoat=label==='배'&&scene.name==='이동 수단';
 const seedling={'상추':'lettuce_young','고추':'pepper_young','토마토':'tomato_young','가지':'eggplant_young','오이':'cucumber_young','호박':'pumpkin_young','양배추':'v4_cabbage_seedling'};
